import 'package:cloud_firestore/cloud_firestore.dart';

DateTime _dt(dynamic v) => v is Timestamp ? v.toDate() : DateTime.tryParse('$v') ?? DateTime.now();

class CrisisReport {
  final String id, title, description, type, locationName, severity, status, reportedBy;
  final double latitude, longitude, confidence, affectedRadiusKm;
  final int peopleAtRisk, blockedRoads;
  final DateTime reportedAt;
  CrisisReport({required this.id, required this.title, required this.description, required this.type, required this.locationName, required this.latitude, required this.longitude, required this.severity, required this.confidence, required this.status, required this.reportedAt, required this.reportedBy, required this.affectedRadiusKm, required this.peopleAtRisk, required this.blockedRoads});
  factory CrisisReport.fromDoc(DocumentSnapshot<Map<String,dynamic>> d){ final m=d.data()!; return CrisisReport(id:d.id,title:m['title']??'',description:m['description']??'',type:m['type']??'',locationName:m['locationName']??'',latitude:(m['latitude']??0).toDouble(),longitude:(m['longitude']??0).toDouble(),severity:m['severity']??'LOW',confidence:(m['confidence']??0).toDouble(),status:m['status']??'New',reportedAt:_dt(m['reportedAt']),reportedBy:m['reportedBy']??'Citizen',affectedRadiusKm:(m['affectedRadiusKm']??0).toDouble(),peopleAtRisk:m['peopleAtRisk']??0,blockedRoads:m['blockedRoads']??0); }
  Map<String,dynamic> toMap()=>{'title':title,'description':description,'type':type,'locationName':locationName,'latitude':latitude,'longitude':longitude,'severity':severity,'confidence':confidence,'status':status,'reportedAt':Timestamp.fromDate(reportedAt),'reportedBy':reportedBy,'affectedRadiusKm':affectedRadiusKm,'peopleAtRisk':peopleAtRisk,'blockedRoads':blockedRoads};
}

class AgentResult { final String id, agentName, status, summary; final double confidence; final List<String> reasoningPoints; final DateTime timestamp; AgentResult({required this.id, required this.agentName, required this.status, required this.summary, required this.confidence, required this.reasoningPoints, required this.timestamp}); factory AgentResult.fromDoc(DocumentSnapshot<Map<String,dynamic>> d){final m=d.data()!; return AgentResult(id:d.id,agentName:m['agentName']??'',status:m['status']??'',summary:m['summary']??'',confidence:(m['confidence']??0).toDouble(),reasoningPoints:List<String>.from(m['reasoningPoints']??[]),timestamp:_dt(m['timestamp']));}}
class AlertMessage { final String id,title,message,language,severity,location,status; final DateTime createdAt; AlertMessage({required this.id,required this.title,required this.message,required this.language,required this.severity,required this.location,required this.status,required this.createdAt}); factory AlertMessage.fromDoc(DocumentSnapshot<Map<String,dynamic>> d){final m=d.data()!; return AlertMessage(id:d.id,title:m['title']??'',message:m['message']??'',language:m['language']??'',severity:m['severity']??'',location:m['location']??'',status:m['status']??'',createdAt:_dt(m['createdAt']));}}
class EmergencyUnit { final String id,type,name,location,status; final int etaMinutes; EmergencyUnit({required this.id,required this.type,required this.name,required this.location,required this.status,required this.etaMinutes}); factory EmergencyUnit.fromDoc(DocumentSnapshot<Map<String,dynamic>> d){final m=d.data()!; return EmergencyUnit(id:d.id,type:m['type']??'',name:m['name']??'',location:m['location']??'',status:m['status']??'',etaMinutes:m['etaMinutes']??0);}}
class SimulationResult { final int beforeCongestion, afterCongestion, beforeEta, afterEta, peopleAtRisk, peopleAlerted; final double congestionReduction, etaImprovement, rescueCoverageImprovement; SimulationResult({required this.beforeCongestion,required this.afterCongestion,required this.beforeEta,required this.afterEta,required this.peopleAtRisk,required this.peopleAlerted,required this.congestionReduction,required this.etaImprovement,required this.rescueCoverageImprovement}); factory SimulationResult.fromDoc(DocumentSnapshot<Map<String,dynamic>> d){final m=d.data()??{}; return SimulationResult(beforeCongestion:m['beforeCongestion']??0,afterCongestion:m['afterCongestion']??0,beforeEta:m['beforeEta']??0,afterEta:m['afterEta']??0,peopleAtRisk:m['peopleAtRisk']??0,peopleAlerted:m['peopleAlerted']??0,congestionReduction:(m['congestionReduction']??0).toDouble(),etaImprovement:(m['etaImprovement']??0).toDouble(),rescueCoverageImprovement:(m['rescueCoverageImprovement']??0).toDouble());}}
